use std::{fs,path::Path,collections::{BTreeMap,BTreeSet}};use serde_json::{Value,json};use sha2::{Digest,Sha256};
const R:&str="/tmp/zopro-sdk-paired-control";
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{format!("{:x}",Sha256::digest(fs::read(p).unwrap()))}
fn save(p:impl AsRef<Path>,v:&Value){fs::write(p,serde_json::to_vec_pretty(v).unwrap()).unwrap()}
fn median(mut xs:Vec<f64>)->f64{assert!(!xs.is_empty());xs.sort_by(f64::total_cmp);if xs.len()%2==1{xs[xs.len()/2]}else{(xs[xs.len()/2-1]+xs[xs.len()/2])/2.}}
fn gm(xs:&[f64])->f64{assert!(!xs.is_empty()&&xs.iter().all(|x|x.is_finite()&&*x>0.));(xs.iter().map(|x|x.ln()).sum::<f64>()/xs.len()as f64).exp()}
fn range(xs:&[f64])->Value{let med=median(xs.to_vec());json!({"median":med,"min":xs.iter().copied().fold(f64::INFINITY,f64::min),"max":xs.iter().copied().fold(0.,f64::max),"MAD":median(xs.iter().map(|x|(x-med).abs()).collect())})}
fn main(){let r=Path::new(R);assert_eq!(read(r.join("capture/result.json"))["status"],"complete");let pins=read(r.join("capture-pins.json"));for(p,h)in pins.as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());}let mut seen:BTreeSet<String>=serde_json::from_value(read(r.join("prior-proofs.json"))).unwrap();assert_eq!(seen.len(),7009);let mut inventory=BTreeMap::new();let mut rows=Vec::new();let mut processes=Vec::new();let mut pids=BTreeSet::new();let jobs=read(r.join("jobs.json"));assert_eq!(jobs.as_array().unwrap().len(),90);
 for job in jobs.as_array().unwrap(){let name=job["name"].as_str().unwrap();let log=fs::read_to_string(r.join("capture").join(name).join("stdout.log")).unwrap();let context:Value=serde_json::from_str(log.lines().find_map(|l|l.strip_prefix("CONTEXT ")).unwrap()).unwrap();assert_eq!(context["before"],context["after"]);assert_eq!(context["workers"],job["workers"]);assert_eq!(context["mode"],job["mode"]);assert_eq!(context["repetition"],job["repetition"]);assert_eq!(context["one_sdk_object"],true);assert_eq!(context["priming"],3);assert_eq!(context["sample_capacity"],238);assert_eq!(context["export_capacity"],14);assert!(pids.insert(context["pid"].as_u64().unwrap()));let expected=job["expected_stages"].as_u64().unwrap()as usize;let workers=job["workers"].as_u64().unwrap()as usize;let receipts=context["before"].as_array().unwrap();assert_eq!(receipts.len(),workers);let mut tids=BTreeSet::new();for(i,w)in receipts.iter().enumerate(){assert_eq!(w["index"],i);assert_eq!(w["allowed"],json!((0..workers).collect::<Vec<_>>()));assert!(tids.insert(w["tid"].as_u64().unwrap()));}
 let stages:Vec<Value>=log.lines().filter_map(|l|l.strip_prefix("STAGE ")).map(|s|serde_json::from_str(s).unwrap()).collect();assert_eq!(stages.len(),expected);let verify=fs::read_to_string(r.join(format!("capture/verify-{name}/stdout.log"))).unwrap();assert!(verify.contains(&format!("verified {expected} distinct proofs across 1 pinned keys")));let mut labels=BTreeSet::new();let mut stage_medians=Vec::new();for(stage_index,s)in stages.into_iter().enumerate(){assert_eq!(s["workers"],job["workers"]);assert_eq!(s["repetition"],job["repetition"]);assert_eq!(s["rounds"],17);assert_eq!(s["mode"],job["mode"]);let block=s["block"].as_u64().unwrap();let label=s["label"].as_str().unwrap();assert!(["a","b"].contains(&label));assert!(block<7&&labels.insert((block,label.to_string())));if expected==1{assert_eq!(s["block"],job["block"]);assert_eq!(s["label"],job["mode"]);}else{assert_eq!(block,stage_index as u64/2);let first=if(block+job["repetition"].as_u64().unwrap())%2==0{"a"}else{"b"};assert_eq!(label,if stage_index%2==0{first}else if first=="a"{"b"}else{"a"});}
 let samples:Vec<f64>=s["samples_ms"].as_array().unwrap().iter().map(|v|{let x=v.as_f64().unwrap();assert!(x.is_finite()&&x>0.);x}).collect();assert_eq!(samples.len(),17);let med=median(samples.clone());stage_medians.push(med);let proof=Path::new(s["proof_path"].as_str().unwrap());let public=Path::new(s["public_path"].as_str().unwrap());assert!(proof.starts_with(job["exports"].as_str().unwrap()));assert_eq!(proof.file_name().unwrap().to_str().unwrap(),format!("b{block}-{label}.proof"));assert_eq!(proof.with_extension("public"),public);assert_eq!(fs::metadata(proof).unwrap().len(),164);assert_eq!(hash(public),job["public_sha256"].as_str().unwrap());assert!(seen.insert(hash(proof)));for p in [proof,public]{assert!(inventory.insert(p.display().to_string(),hash(p)).is_none());}
 let mut metrics=s.clone();metrics["request_ms"]=json!(med);metrics["sample_stats"]=range(&samples);metrics["first5_ms"]=json!(median(samples[..5].to_vec()));metrics["last5_ms"]=json!(median(samples[12..].to_vec()));metrics["last_first_ratio"]=json!(metrics["last5_ms"].as_f64().unwrap()/metrics["first5_ms"].as_f64().unwrap());metrics["CPU_ms_per_request"]=json!((s["user_cpu_ms"].as_f64().unwrap()+s["system_cpu_ms"].as_f64().unwrap())/17.);metrics["voluntary_per_request"]=json!(s["voluntary_switches"].as_f64().unwrap()/17.);metrics["involuntary_per_request"]=json!(s["involuntary_switches"].as_f64().unwrap()/17.);metrics["minor_faults_per_request"]=json!(s["minor_faults"].as_f64().unwrap()/17.);rows.push(json!({"job":name,"context":job["context"],"repetition":job["repetition"],"workers":job["workers"],"stage_index":stage_index,"stage":metrics}));}
 processes.push(json!({"job":job,"receipt":context,"stage_median_stats":range(&stage_medians),"last_stage_first_stage_ratio":stage_medians.last().unwrap()/stage_medians[0]}));}
 assert_eq!(rows.len(),168);assert_eq!(inventory.len(),336);assert_eq!(seen.len(),7177);assert_eq!(pids.len(),90);let mut cases=BTreeMap::new();let mut repetitions=BTreeMap::new();let mut crossings=Vec::new();let mut median_crossings=Vec::new();for context in ["paired","fresh"]{for workers in [16,32]{let mut all_ratios=Vec::new();let mut failures=0;let mut med_fails=0;for rep in 0..3{let mut ratios=Vec::new();for block in 0..7{let value=|label:&str|rows.iter().find(|r|r["context"]==context&&r["workers"]==workers&&r["repetition"]==rep&&r["stage"]["block"]==block&&r["stage"]["label"]==label).unwrap()["stage"]["request_ms"].as_f64().unwrap();let ratio=value("b")/value("a");if !(1./1.05..=1.05).contains(&ratio){crossings.push(format!("{context}-w{workers}-r{rep}-b{block}:B/A={ratio}"));failures+=1;}ratios.push(ratio);}let med=median(ratios.clone());if !(1./1.03..=1.03).contains(&med){median_crossings.push(format!("{context}-w{workers}-r{rep}:median B/A={med}"));med_fails+=1;}repetitions.insert(format!("{context}-w{workers}-r{rep}"),json!({"block_ratios":ratios,"median_ratio":med,"geometric_ratio":gm(&ratios),"range":range(&ratios)}));all_ratios.extend(ratios);}
 let rs:Vec<_>=rows.iter().filter(|r|r["context"]==context&&r["workers"]==workers).collect();assert_eq!(rs.len(),42);let values=|key:&str|->Vec<f64>{rs.iter().map(|r|r["stage"][key].as_f64().unwrap()).collect()};let ms=values("request_ms");let cpu=values("CPU_ms_per_request");let rss=values("whole_process_maxrss_kib");let mut labels=BTreeMap::new();for label in ["a","b"]{let v:Vec<_>=rs.iter().filter(|r|r["stage"]["label"]==label).map(|r|r["stage"]["request_ms"].as_f64().unwrap()).collect();assert_eq!(v.len(),21);labels.insert(label,range(&v));}cases.insert(format!("{context}-w{workers}"),json!({"context":context,"workers":workers,"labels":labels,"median_stage_ms":median(ms.clone()),"request_ms_stats":range(&ms),"median_CPU_ms_per_request":median(cpu),"maximum_lifetime_RSS_mib":rss.iter().copied().fold(0.,f64::max)/1024.,"ratio_stats":range(&all_ratios),"ratio_geometric_mean":gm(&all_ratios),"all21_block_ratios":all_ratios,"block_bound_crossings":failures,"repetition_median_bound_crossings":med_fails,"last_first_stats":range(&values("last_first_ratio")),"involuntary_per_request_stats":range(&values("involuntary_per_request")),"voluntary_per_request_stats":range(&values("voluntary_per_request"))}));}}
 let mut after=BTreeMap::new();for p in ["/proc/loadavg","/proc/stat","/proc/self/cgroup","/sys/fs/cgroup/cpu.stat","/sys/fs/cgroup/cpu.max","/sys/devices/system/cpu/cpufreq/policy0/scaling_governor","/sys/devices/system/cpu/cpufreq/policy0/scaling_cur_freq"]{after.insert(p,match fs::read_to_string(p){Ok(s)=>json!({"text":s}),Err(e)=>json!({"unavailable":e.to_string()})});}save(r.join("host-after.json"),&json!(after));save(r.join("proof-inventory.json"),&json!(inventory));save(r.join("rows.json"),&json!(rows));save(r.join("processes.json"),&json!(processes));save(r.join("analysis.json"),&json!({"cases":cases,"repetitions":repetitions,"block_bound_crossings":crossings,"repetition_median_bound_crossings":median_crossings,"SDK_requests":3126,"timed_requests":2856,"priming_requests":270,"processes":90,"stages":168,"independent_gnark_exports":168,"proof_public_members":336,"next_prior_count":7177,"all_worker_receipts_unchanged":true,"new_algorithm":false,"new_cycle_profiles":0,"candidate_compared":false,"adopted":false,"goal_achieved":false}));println!("3126SDK168independentGnark;next7177;blockcrossings{};repetitionmedian{}",crossings.len(),median_crossings.len());}
